        """
        if int(s) < 100:
            words = []
            if int(s) // 10:
                words.append(self.NUMBER_TEN[int(s) // 10])
            if int(s) % 10:
                words.append(self.NUMBER[int(s) % 10])
            return " ".join(words)
        else:
            words = []
            if int(s) // 100:
                words.append(self.NUMBER[int(s) // 100])
                words.append("HUNDRED")
            if int(s) % 100:
                words.append(self.trans_two(s % 100))
            return " ".join(words)

    def parse_more(self, i):
        """
        Parses the thousand/million/billion suffix based on the index
        :param i: int, the index representing the magnitude (thousand, million, billion)
        :return: str, the corresponding suffix for the magnitude
        """
        if i == 0:
            return ""
        elif i == 1:
            return "THOUSAND"
        elif i == 2:
            return "MILLION"
        elif i == 3:
